studio.querySelector('[data-seed-tests]').onclick=()=>{if(!editable())return;const id=document.getElementById('challenge-choice')?.value;const templates=testTemplates[id];if(!templates){n('Sélectionnez d’abord un challenge.','error');return}for(const [name,input,expected] of templates)if(!state.cases.some(t=>t.name===name))state.cases.push({name,input,expected,actual:'',status:'pending'});persist();render()};
