for(const kind of ['task','case']){studio.querySelector('[data-add-'+kind+']').onclick=()=>add(kind);studio.querySelector('[data-new-'+kind+']').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();add(kind)}};studio.querySelectorAll('[data-remove-'+kind+']').forEach(el=>el.onclick=()=>{if(editable()&&confirm('Supprimer cet élément ?')){state[kind==='task'?'tasks':'cases'].splice(Number(el.getAttribute('data-remove-'+kind)),1);persist();render()}})}
studio.querySelectorAll('[data-task-name]').forEach(el=>el.oninput=()=>{if(editable()){state.tasks[Number(el.dataset.taskName)].name=el.value;persist()}});
studio.querySelectorAll('[data-task]').forEach(el=>el.onchange=()=>{if(editable()){const task=state.tasks[Number(el.dataset.task)];if(el.value==='done'&&!String(task.proof||'').trim()){n('Ajoutez une preuve avant de déclarer cette tâche terminée.','error');el.value=task.status;return}task.status=el.value;persist();render()}});
