const impactCard=document.createElement('section');impactCard.className='card studio-content impact-studio';impactCard.hidden=true;const impactInput=document.createElement('input');impactInput.type='hidden';impactInput.id='impact-model';impactInput.value=JSON.stringify(w.submission?.impact||{});impactCard.append(impactInput);const impactView=document.createElement('div');impactCard.append(impactView);app.querySelector('.grid').append(impactCard);let impactState=decodeSummary(impactInput.value);const factors=[['volume','Opérations par mois','Ex. 1 000',0,100000000,1],['minutes','Minutes économisées par opération','Ex. 5',0,1440,.1],['hourly','Coût horaire chargé (MAD)','Ex. 60',0,100000,.01],['value','Gain additionnel par opération (MAD)','Hors économie de temps',0,100000000,.01],['adoption','Taux d’adoption central (%)','Ex. 60',0,100,1],['setup','Investissement initial (MAD)','Ex. 5 000',0,1000000000,.01],['monthly','Coût récurrent mensuel (MAD)','Ex. 500',0,1000000000,.01]];impactView.innerHTML='<div class="studio-kicker">LIVRABLE · VALEUR MÉTIER</div><h2>Business Impact Simulator</h2><p>Estimez les gains à partir de vos hypothèses. Saisissez zéro si un levier ne s’applique pas. Évitez de compter deux fois le même gain.</p><div class="impact-layout"><div class="impact-inputs">'+factors.map(([k,label,hint,min,max,step])=>'<label>'+esc(label)+'<input type="number" min="'+min+'" max="'+max+'" step="'+step+'" placeholder="'+esc(hint)+'" data-impact="'+k+'" data-node="impact" value="'+esc(impactState[k]??'')+'"></label>').join('')+'<label>Sources et justification<textarea data-impact="basis" data-node="impact" rows="3" placeholder="Observation, mesure du prototype ou hypothèse à valider">'+esc(impactState.basis||'')+'</textarea></label></div><div class="impact-results" role="status" aria-live="polite"></div></div><p class="impact-method">Méthode : 12 mois à volume constant. Adoption prudente = 50 % du taux central ; ambitieuse = 125 %, plafonnée à 100 %. Net = gains bruts − coûts récurrents − investissement initial. Ce modèle ne tient pas compte de la fiscalité ni de l’actualisation.</p>';
function drawImpact(){const target=impactView.querySelector('.impact-results'),rows=estimateImpact(impactState);if(!rows){target.innerHTML='<div class="impact-empty"><h3>Votre estimation apparaîtra ici</h3><p>Renseignez les sept hypothèses numériques avec des valeurs valides.</p></div>';return}const scale=Math.max(1,...rows.map(s=>Math.abs(s.net)));target.innerHTML='<div class="impact-hero"><small>SCÉNARIO CENTRAL · NET ANNÉE 1</small><strong>'+esc(impactMoney(rows[1].net))+'</strong><span>'+new Intl.NumberFormat('fr-MA',{maximumFractionDigits:1}).format(rows[1].hours)+' h économisées / mois</span></div>'+rows.map(s=>'<article class="impact-scenario"><div class="row"><strong>'+esc(s.label)+'</strong><span>'+esc(impactMoney(s.net))+'</span></div><div class="impact-track"><progress aria-label="Valeur absolue du gain net '+esc(s.label)+'" max="'+scale+'" value="'+Math.abs(s.net)+'" class="'+(s.net<0?'negative':'positive')+'"></progress></div><small>'+Math.round(s.adoption*100)+' % adoption · '+(s.payback===null?'Retour non atteint à rythme constant':s.payback.toFixed(1)+' mois de retour estimé')+'</small></article>').join('')}
