const fields=[...app.querySelectorAll('input:not([data-node]),textarea:not([data-node])')].filter(el=>!el.closest('#matching-panel'));if(submitted){fields.forEach(el=>el.disabled=true);document.querySelector('#save').disabled=true;document.querySelector('#submit').disabled=true;document.querySelector('#submit').textContent='Dossier déjà soumis'}function body(){return{...(challengeInput.value?{challenge:{...(w.challenge||{}),id:challengeInput.value}}:{}),problem:{summary:document.querySelector('#problem').value},solution:{summary:document.querySelector('#solution').value},tests:{...(w.tests||{}),summary:document.querySelector('#tests').value,benchmark:benchInput.value?decodeSummary(benchInput.value):null},redteam:decodeSummary(redInput.value),decisions:decodeSummary(labInput.value),submission:{...(w.submission||{}),story:decodeSummary(pitchInput.value),impact:decodeSummary(impactInput.value),result:document.querySelector('#result').value,limits:document.querySelector('#limits').value,repo:document.querySelector('#repo').value}}}const stageFields={problem:'problem',solution:'solution',tests:'build',result:'pitch',limits:'pitch',repo:'pitch'};let scheduleState=initialSchedule,clockOffset=initialSchedule.now-Date.now();const timeline=app.querySelector('#event-timeline');const studioGrid=app.querySelector('.grid');studioGrid.classList.add('innovation-studio');const introCard=timeline.closest('section');introCard.classList.add('studio-navigation');introCard.querySelector('h2').textContent='Mon studio';introCard.querySelector('p').textContent=simulation?'Simulation isolée.':'Votre travail est sauvegardé au fil de la journée.';const contentCards=[...studioGrid.querySelectorAll('section.half')];contentCards.forEach(el=>el.classList.add('studio-content'));const actionBar=document.createElement('section');actionBar.className='studio-actions';actionBar.append(document.querySelector('#save'),document.querySelector('#submit'));studioGrid.append(actionBar);const missionHeader=docu