studioGrid.append(challengeCard,dataHub,contentCards[0],benchCard,labCard,redCard,contentCards[1],impactCard,pitchCard,reviewCard,helpCard,actionBar);const studioMain=document.createElement('div');studioMain.className='studio-main';for(const child of [...studioGrid.children])if(child!==introCard)studioMain.append(child);studioGrid.append(studioMain);const mobileNav=document.createElement('div');mobileNav.className='studio-mobile-nav';mobileNav.innerHTML='<div><span class="studio-kicker">MON STUDIO</span><strong id="mobile-mission-title">Vue d’ensemble</strong><small id="mobile-save-status" role="status">Dossier chargé</small></div><button type="button" class="button ghost" id="mobile-mission-toggle" aria-expanded="false">Les missions</button>';studioGrid.prepend(mobileNav);mobileNav.querySelector('button').onclick=()=>{const expanded=studioGrid.classList.toggle('mobile-nav-open');mobileNav.querySelector('button').setAttribute('aria-expanded',String(expanded));if(expanded)introCard.querySelector('[aria-current]')?.focus()};function goMission(id){activeStage=id;studioGrid.classList.remove('mobile-nav-open');mobileNav.querySelector('button').setAttribute('aria-expanded','false');paintSchedule();studioMain.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});const heading=(id==='home'?homeCard:missionHeader).querySelector('h2');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true})}}paintSchedule();let ticks=0;const scheduleTimer=setInterval(async()=>{if(!timeline.isConnected){clearInterval(scheduleTimer);return}if(++ticks%15===0){try{const fresh=await request('schedule');const wasOpen=scheduleState.stages.find(x=>x.id==='matching')?.unlocked;scheduleState=fresh;clockOffset=fresh.now-Date.now();if(!wasOpen&&fresh.stages.find(x=>x.id==='matching')?.unlocked)panel.querySelector('#match-refresh').click()}catch{}}paintSchedule()},1000);let dirty=false,timer=null,inflight=null,revision=0,conflict=fals