function reportSaveError(err){if(!timeline.isConnected)return;conflict=conflict||err.code==='VERSION_CONFLICT'||err.code==='TEAM_CHANGED'||err.status===401||err.status===403||err.status===409;recovery.hidden=false;recovery.querySelector('#recovery-message').textContent=err.message+(conflict?' Copiez vos modifications avant de recharger le dossier.':' Vérifiez votre connexion puis réessayez.');recovery.querySelector('#retry-recovery').hidden=conflict;if(status())status().textContent='Modifications non enregistrées';}
